	if cached, ok := repoHooksDirCache.Load(key); ok {
		return cached.(string), nil
	}
	hooksDir, err := getHooksDirInPath(ctx, repoRoot)
	if err != nil {
		return "", err
	}
	repoHooksDirCache.Store(key, hooksDir)
	return hooksDir, nil
}

