// generated wrapper, dispatching through a shim binary named `lefthook`
// rather than calling Entire's script inline.
//
// The shim matters. Production tells "Lefthook owns this hook" from the
// wrapper's dispatch line, and real Lefthook always invokes a binary whose
// basename is `lefthook` — by name, or by absolute path for its node_modules
// branches. A fixture that execs .lefthook-local/<hook>/entire.sh directly
// has no such line, so it is not a Lefthook launcher in any sense production
// can detect, and recognizing it once required a whitelist of these exact
// fixture strings in shipping code. This shape needs no special case and
// exercises the same path a real install does, without requiring the real
// binary on PATH.
func installSimulatedLefthookHooks(t *testing.T, repoRoot string) {
	t.Helper()

	shimDir := filepath.Join(repoRoot, ".lefthook-bin")
	require.NoError(t, os.MkdirAll(shimDir, 0o755))
	// Stands in for the lefthook binary: resolves the hook's owned script the
	// way `lefthook run <hook>` would and execs it with the hook's own args.
	shim := `#!/bin/sh
# simulated lefthook binary
[ "$1" = "run" ] || exit 0
hook="$2"
shift 2
script="$PWD/.lefthook-local/$hook/entire.sh"
[ -x "$script" ] || exit 0
exec "$script" "$@"
`
	require.NoError(t, os.WriteFile(filepath.Join(shimDir, "lefthook"), []byte(shim), 0o755))

	hooksDir := filepath.Join(repoRoot, ".git", "hooks")
	require.NoError(t, os.MkdirAll(hooksDir, 0o755))
	for _, hook := range strategy.ManagedGitHookNames() {
		content := fmt.Sprintf(`#!/bin/sh

if [ "$LEFTHOOK_VERBOSE" = "1" -o "$LEFTHOOK_VERBOSE" = "true" ]; then
  set -x
fi

if [ "$LEFTHOOK" = "0" ]; then
  exit 0
fi

# lefthook generated wrapper
call_lefthook()
{
  "$PWD/.lefthook-bin/lefthook" "$@"
}

call_lefthook run "%s" "$@"
`, hook)
		require.NoError(t, os.WriteFile(filepath.Join(hooksDir, hook), []byte(content), 0o755))
	}
}

'''
